/**
 * Claude Desktop's side of brokered MCP endpoints.
 *
 * Writes `mcpServers` entries in the Claude-3p `claude_desktop_config.json`.
 * Each entry is generated by Maximal: a local stdio command that runs the
 * broker's adapter against the stable main-port URL `/mcp/<id>`, with the
 * key in the entry's environment rather than on a command line.
 *
 * Only entries Maximal recorded as written (`owned`) and that still carry
 * Maximal's signature are ever changed or removed. An entry the user already
 * had under the same name is left alone and reported as skipped; one Maximal
 * can't write because the adapter is missing is reported as unavailable.
 */

import consola from "consola"
import fs from "node:fs"
import os from "node:os"
import path from "node:path"

import type {
  McpClientConfigurator,
  McpClientEntry,
  McpReconcileResult,
} from "~/lib/mcp-broker/client-sync"

import { getConfig } from "~/lib/config/config"
import { isMaximalMcpUrl, parseStdioEntry } from "~/lib/mcp-broker/client-sync"
import { brokerExecutableCandidates } from "~/lib/mcp-broker/configuration"

import {
  atomicWriteJson,
  configLibraryConflict,
  getClaude3pDir,
  isConfigLibraryApplied,
  readJsonObject,
} from "./config"

const ADAPTER_API_KEY_ENV = "MAXIMAL_MCP_API_KEY"

interface McpServerEntry {
  command: string
  args: Array<string>
  env?: Record<string, string>
}

export interface ClaudeDesktopMcpOptions {
  /** Leave undefined to use getClaude3pDir's own default, so callers (and
   *  tests that redirect it) resolve the same directory as the profile. */
  home?: string
  resolveBrokerPath?: () => string | undefined
  available?: () => Promise<boolean>
  /** Whether another provider's gateway profile is applied in Desktop. */
  otherProviderApplied?: () => boolean
  /** Where to look for the regular Claude Desktop config; see
   *  `regularClaudeDesktopConfigPaths`. */
  regularConfig?: RegularConfigLocation
}

/** What locates the regular Claude Desktop config: the platform, and on
 *  Windows the `APPDATA` and `LOCALAPPDATA` folders. Each defaults to this
 *  machine's; tests pass their own, so they never read the real user's. */
export interface RegularConfigLocation {
  home?: string
  platform?: NodeJS.Platform
  appData?: string
  localAppData?: string
}

/** Ours only when it runs the broker adapter against this endpoint's
 *  Maximal URL, on whatever port Maximal used when it was written. */
export function isOwnedMcpEntry(
  value: unknown,
  entry: Pick<McpClientEntry, "id">,
): boolean {
  if (typeof value !== "object" || value === null) return false
  const { command, args } = value as Record<string, unknown>
  if (typeof command !== "string" || !Array.isArray(args)) return false
  const name = path.basename(command.replaceAll("\\", "/"))
  return (
    (name === "maximal-mcp-broker" || name === "maximal-mcp-broker.exe")
    && args[0] === "stdio-adapter"
    && args[1] === "--url"
    && isMaximalMcpUrl(args[2], entry.id)
  )
}

function defaultBrokerPath(): string | undefined {
  return brokerExecutableCandidates(getConfig().mcpBroker?.executablePath).find(
    (candidate) => fs.existsSync(candidate),
  )
}

function buildEntry(entry: McpClientEntry, brokerPath: string): McpServerEntry {
  return {
    command: brokerPath,
    args: ["stdio-adapter", "--url", entry.url],
    ...(entry.apiKey === undefined ?
      {}
    : { env: { [ADAPTER_API_KEY_ENV]: entry.apiKey } }),
  }
}

export function claudeDesktopConfigPath(home?: string): string {
  return path.join(getClaude3pDir(home), CONFIG_FILE)
}

const CONFIG_FILE = "claude_desktop_config.json"

/**
 * Where the regular (first-party) Claude Desktop config can be, in the order
 * to look. Read only, to find servers the user set up there. On macOS it is
 * a sibling of the Claude-3p directory. On Windows it is in `%APPDATA%`
 * (Claude-3p is in `%LOCALAPPDATA%`), or, for the Microsoft Store (MSIX)
 * app, in its package's redirected copy of `%APPDATA%`:
 * `%LOCALAPPDATA%\Packages\Claude_<publisher id>\LocalCache\Roaming\Claude`.
 */
export function regularClaudeDesktopConfigPaths({
  home,
  platform = process.platform,
  appData = process.env.APPDATA,
  localAppData = process.env.LOCALAPPDATA,
}: RegularConfigLocation = {}): Array<string> {
  if (platform !== "win32") {
    return [
      path.join(path.dirname(getClaude3pDir(home)), "Claude", CONFIG_FILE),
    ]
  }
  const userHome = home ?? os.homedir()
  const roaming = appData ?? path.join(userHome, "AppData", "Roaming")
  const local = localAppData ?? path.join(userHome, "AppData", "Local")
  const packages = path.join(local, "Packages")
  let storeApps: Array<string> = []
  try {
    storeApps = fs
      .readdirSync(packages)
      .filter((name) => name.startsWith("Claude_"))
      .sort()
  } catch {
    // No Packages folder: no Store apps.
  }
  return [
    path.join(roaming, "Claude", CONFIG_FILE),
    ...storeApps.map((name) =>
      path.join(packages, name, "LocalCache", "Roaming", "Claude", CONFIG_FILE),
    ),
  ]
}

function serversIn(file: string): Record<string, unknown> {
  const servers = readJsonObject(file)?.mcpServers
  return typeof servers === "object" && servers !== null ?
      (servers as Record<string, unknown>)
    : {}
}

export function createClaudeDesktopMcp(
  options: ClaudeDesktopMcpOptions = {},
): McpClientConfigurator {
  const resolveBrokerPath = options.resolveBrokerPath ?? defaultBrokerPath
  return {
    clientId: "claude-desktop",
    apiKeyLabel: "claude-desktop",
    // Desktop reads this file only at launch, and its routing stays applied
    // across Maximal restarts too (see ./reconcile.ts).
    removeOnShutdown: false,
    available:
      options.available ?? (() => Promise.resolve(isConfigLibraryApplied())),
    unavailableReason() {
      const other =
        options.otherProviderApplied
        ?? (() => configLibraryConflict(options.home) !== null)
      return other() ? "other-provider-profile" : undefined
    },
    // File edits only, so these finish synchronously either way.
    reconcile(desired, owned) {
      return Promise.resolve(
        reconcileFile({
          topPath: claudeDesktopConfigPath(options.home),
          desired,
          owned,
          brokerPath: desired.length > 0 ? resolveBrokerPath() : undefined,
        }),
      )
    },
    releaseOffline(owned) {
      return reconcileFile({
        topPath: claudeDesktopConfigPath(options.home),
        desired: [],
        owned,
        brokerPath: undefined,
      })
    },
    existingStdioEntry(id) {
      // Never adopt Maximal's own adapter entry, owned or not.
      const notOurs = (value: unknown): unknown =>
        isOwnedMcpEntry(value, { id }) ? undefined : value
      const files = [
        claudeDesktopConfigPath(options.home),
        ...regularClaudeDesktopConfigPaths({
          home: options.home,
          ...options.regularConfig,
        }),
      ]
      for (const file of files) {
        const entry = notOurs(serversIn(file)[id])
        if (entry !== undefined) return parseStdioEntry(entry)
      }
      return parseStdioEntry(undefined)
    },
  }
}

function reconcileFile(input: {
  topPath: string
  desired: Array<McpClientEntry>
  owned: Array<string>
  brokerPath: string | undefined
}): McpReconcileResult {
  const { topPath, desired, owned, brokerPath } = input
  const top = readJsonObject(topPath) ?? {}
  const existing =
    typeof top.mcpServers === "object" && top.mcpServers !== null ?
      (top.mcpServers as Record<string, unknown>)
    : {}
  const result: McpReconcileResult = {
    owned: [],
    added: [],
    removed: removableIds(existing, desired, owned),
    skipped: [],
    unavailable: [],
  }
  const writes: Record<string, McpServerEntry> = {}

  for (const entry of desired) {
    const current = existing[entry.id]
    const ours = owned.includes(entry.id) && isOwnedMcpEntry(current, entry)
    if (current !== undefined && !ours) {
      result.skipped.push(entry.id)
    } else if (brokerPath !== undefined) {
      writes[entry.id] = buildEntry(entry, brokerPath)
      result.owned.push(entry.id)
      if (current === undefined) result.added.push(entry.id)
    } else if (ours) {
      // Can't generate an entry without the adapter; keep the one we own.
      result.owned.push(entry.id)
    } else {
      result.unavailable.push({ id: entry.id, reason: "adapter-missing" })
    }
  }

  if (result.unavailable.length > 0) {
    consola.warn(
      "Claude Desktop MCP servers not added: maximal-mcp-broker not found",
    )
  }
  const next = {
    ...Object.fromEntries(
      Object.entries(existing).filter(([id]) => !result.removed.includes(id)),
    ),
    ...writes,
  }
  if (JSON.stringify(next) !== JSON.stringify(existing)) {
    const { mcpServers: _previous, ...rest } = top
    atomicWriteJson(
      topPath,
      Object.keys(next).length === 0 ? rest : { ...rest, mcpServers: next },
    )
  }
  return result
}

/** Owned entries no longer desired that still carry Maximal's signature. */
function removableIds(
  existing: Record<string, unknown>,
  desired: Array<McpClientEntry>,
  owned: Array<string>,
): Array<string> {
  return owned.filter(
    (id) =>
      !desired.some((entry) => entry.id === id)
      && isOwnedMcpEntry(existing[id], { id }),
  )
}

export const claudeDesktopMcp = createClaudeDesktopMcp()
